using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
// External authoring only. No gameplay component is imported or changed.
public static class B1InteriorApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_InteriorRedesign/";static string O=>R+"/Docs/Review/2026-11-12_B1_Interior/";
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B1/";
 static Vector3 V(JToken q)=>new Vector3((float)q[0],(float)q[1],(float)q[2]);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 required");return s;}
 static void Record(Transform root){foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}}
 public static object Apply(){var s=Check();Directory.CreateDirectory(O);var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;var p=JObject.Parse(File.ReadAllText(H+"layout.json"));var models=JObject.Parse(File.ReadAllText(H+"models_environment.json"));var cols=JObject.Parse(File.ReadAllText(H+"structural_colliders.json"));
  AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
  foreach(var m in models){var q=m.Value;var importer=(ModelImporter)AssetImporter.GetAtPath((string)q["asset"]);if(!importer)throw new Exception("Missing model "+q["asset"]);importer.importAnimation=false;importer.animationType=ModelImporterAnimationType.None;importer.isReadable=false;importer.importNormals=ModelImporterNormals.Import;importer.importTangents=ModelImporterTangents.CalculateMikk;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.materialLocation=ModelImporterMaterialLocation.InPrefab;foreach(string mat in q["materials"].Select(v=>(string)v).Distinct()){var material=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/"+mat+".mat");if(!material)throw new Exception("Missing shared material "+mat);importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),mat),material);}importer.SaveAndReimport();}
  Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("B1 full interior redesign");Undo.RegisterFullObjectHierarchyUndo(root.gameObject,"B1 interior layout");int moved=0,added=0;
  foreach(var q in p["placements"]){string room=(string)q["room"],name=(string)q["name"];var eq=root.Find("B1_"+room+"_Sector/Equipment");var t=eq.Find(name);if(!t){if(q["template"]==null)throw new Exception("Missing existing prop "+name);var template=root.Find("B1_"+(string)q["templateRoom"]+"_Sector/Equipment/"+(string)q["template"]);if(!template)throw new Exception("Missing template");t=UnityEngine.Object.Instantiate(template.gameObject,eq).transform;t.name=name;Undo.RegisterCreatedObjectUndo(t.gameObject,"Reuse B1 furniture");added++;}else if(Vector3.Distance(t.localPosition,V(q["position"]))>.002f||Quaternion.Angle(t.localRotation,Quaternion.Euler(0,(float)q["yaw"],0))>.01f)moved++;
   t.localPosition=V(q["position"]);t.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);
  }
  int structural=0;foreach(var m in models){string code=m.Key.Split('_')[2];var sector=root.Find("B1_"+code+"_Sector");var old=sector.Find("InteriorRedesign");if(old)Undo.DestroyObjectImmediate(old.gameObject);var container=new GameObject("InteriorRedesign");container.transform.SetParent(sector,false);Undo.RegisterCreatedObjectUndo(container,"B1 interior structure");var mesh=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((string)m.Value["asset"]),container.transform);mesh.name="B1_"+code+"_InteriorArchitecture";foreach(var c in cols[code]){var g=new GameObject((string)c["name"]+"_Collision");g.transform.SetParent(container.transform,false);g.transform.localPosition=V(c["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)c["yaw"],0);g.AddComponent<BoxCollider>().size=V(c["size"]);structural++;}foreach(var t in container.GetComponentsInChildren<Transform>())GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.OccluderStatic|StaticEditorFlags.OccludeeStatic|StaticEditorFlags.ReflectionProbeStatic);}
  int relit=0;foreach(var g in p["interior"]["lights"].GroupBy(q=>(string)q["room"])){var ls=root.Find("B1_"+g.Key+"_Sector/Lighting").GetComponentsInChildren<Light>(true).Where(l=>l.transform.parent.name.Contains("_CeilingLight_")).OrderBy(l=>l.transform.parent.name).ToArray();var goals=g.ToArray();if(ls.Length<goals.Length)throw new Exception("Not enough existing lights "+g.Key);for(int i=0;i<goals.Length;i++){var l=ls[i];var fixture=l.transform.parent;fixture.localPosition=V(goals[i]["point"])+Vector3.up*.06f;fixture.localRotation=Quaternion.identity;l.transform.localRotation=Quaternion.Euler(90,0,0);l.intensity=5.8f;l.range=8;l.spotAngle=112;l.innerSpotAngle=78;l.color=new Color(1,.94f,.84f);relit++;}}
  Record(root);Physics.SyncTransforms();Undo.CollapseUndoOperations(group);EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);
  var result=new{scene=s.path,movedExisting=moved,reusedAdded=added,placements=p["placements"].Count(),architectureModels=models.Count,structuralColliders=structural,repositionedExistingLights=relit,enabledLights=root.GetComponentsInChildren<Light>().Count(l=>l.enabled),runtimeScriptsAdded=0};File.WriteAllText(O+"applied.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Audit(){var s=Check();var root=GameObject.Find("B1_ResearchAndStaffFloor");var p=JObject.Parse(File.ReadAllText(H+"layout.json"));var errors=new List<string>();foreach(var q in p["placements"]){var t=root.transform.Find("B1_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);if(!t){errors.Add("Missing "+q["name"]);continue;}if(Vector3.Distance(t.localPosition,V(q["position"]))>.002f)errors.Add("Position "+t.name);if(Quaternion.Angle(t.localRotation,Quaternion.Euler(0,(float)q["yaw"],0))>.01f)errors.Add("Rotation "+t.name);}
  foreach(var f in root.GetComponentsInChildren<MeshFilter>(true))if(!f.sharedMesh)errors.Add("Missing mesh "+f.name);foreach(var rr in root.GetComponentsInChildren<Renderer>(true))if(rr.sharedMaterials.Any(m=>!m))errors.Add("Missing material "+rr.name);
  string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;var candidates=root.GetComponentsInChildren<Transform>(true).GroupBy(PathOf).ToDictionary(g=>g.Key,g=>g.ToList());var baseline=JObject.Parse(File.ReadAllText(H+"before_scene.json"));int kept=0;foreach(var q in baseline["protectedTransforms"]){string path=(string)q["path"];if(path==root.name||path.Contains("/B1_Reflections/"))continue;if(!candidates.TryGetValue(path,out var list)){errors.Add("Protected object missing "+path);continue;}var t=list.FirstOrDefault(v=>Vector3.Distance(v.localPosition,V(q["pos"]))<.0001f&&Vector3.Distance(v.localScale,V(q["scale"]))<.0001f&&Quaternion.Angle(v.localRotation,Quaternion.Euler(V(q["rot"])))<.015f&&v.gameObject.activeSelf==(bool)q["active"]);if(!t){errors.Add("Protected transform "+path);continue;}list.Remove(t);if(Vector3.Distance(t.localPosition,V(q["pos"]))>.0001f||Vector3.Distance(t.localScale,V(q["scale"]))>.0001f||Quaternion.Angle(t.localRotation,Quaternion.Euler(V(q["rot"])))>.015f||t.gameObject.activeSelf!=(bool)q["active"])errors.Add("Protected transform "+path);else kept++;}
  var result=new{scene=s.path,saved=!s.isDirty,placements=p["placements"].Count(),protectedTransforms=kept,errors,missingScripts=root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),activeLights=root.GetComponentsInChildren<Light>().Count(l=>l.enabled),shadowLights=root.GetComponentsInChildren<Light>().Count(l=>l.enabled&&l.shadows!=LightShadows.None),lodGroups=root.GetComponentsInChildren<LODGroup>(true).Length,newReadableMeshes=root.GetComponentsInChildren<MeshFilter>().Count(f=>f.sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).Contains("BL_RI_")&&f.sharedMesh.isReadable)};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
}
